java.io.File inputFile = new java.io.File(grid_png);
java.io.File outDir = new java.io.File(output_dir);
if (!outDir.exists()) {
    outDir.mkdirs();
}

net.coobird.thumbnailator.Thumbnails.of(inputFile)
    .size(50, 50)
    .toFiles(outDir, net.coobird.thumbnailator.name.Rename.PREFIX_HYPHEN_THUMBNAIL);

java.io.File expectedOutputFile = new java.io.File(outDir, "thumbnail-" + inputFile.getName());
assert expectedOutputFile.exists() : "Output file does not exist: " + expectedOutputFile;

java.awt.image.BufferedImage result = javax.imageio.ImageIO.read(expectedOutputFile);
assert result != null : "Output file is not a valid image";
assert result.getWidth() == 50 || result.getHeight() == 50 : "Thumbnail dimensions incorrect";
assert result.getWidth() <= 50 && result.getHeight() <= 50 : "Thumbnail dimensions exceed 50x50";

System.out.println("__CHECK__ toFiles " + expectedOutputFile.getName() + " " + result.getWidth() + "x" + result.getHeight());

